alter table public.cineo_backup_records add column key_envelope jsonb not null default '{}';
create function public.cineo_backup_snapshot() returns jsonb language plpgsql stable security invoker set search_path='' as $$declare t text;rows jsonb;total integer;out jsonb:='{}';begin
 foreach t in array array['cineo_shows','cineo_episodes','cineo_profiles','cineo_categories','cineo_collections','cineo_editorial','cineo_preferences','cineo_ratings','cineo_lists','cineo_list_items','cineo_viewers','cineo_viewer_progress','cineo_viewer_saved','cineo_follows','cineo_progress','cineo_saved','cineo_likes','cineo_comments','cineo_comment_likes','cineo_show_info','cineo_episode_notes','cineo_polls','cineo_poll_votes','cineo_library_choices','cineo_bookmarks','cineo_experience','cineo_surveys','cineo_survey_votes','cineo_notices','cineo_feature_flags','cineo_release_news','cineo_tickets','cineo_appeals','cineo_cases','cineo_case_notes','cineo_case_actions','cineo_revisions','cineo_proposals']loop
 execute format('select count(*) from public.%I',t) into total;if total>5000 then raise exception 'Backup pelo app limitado a 5.000 registros por tabela. Use o backup completo do banco para este volume.';end if;
 execute format('select coalesce(jsonb_agg(to_jsonb(r)),''[]''::jsonb) from public.%I r',t) into rows;out=out||jsonb_build_object(t,rows);end loop;return jsonb_build_object('version',8,'created_at',now(),'tables',out,'media_included',false,'auth_included',false);end$$;
create function public.cineo_restore_metadata(payload jsonb,apply_missing boolean default false) returns jsonb language plpgsql security invoker set search_path='' as $$declare t text;rows jsonb;report jsonb:='[]';n integer;added integer;uid_text text;begin
 if (payload->>'version')::integer<>8 or jsonb_typeof(payload->'tables')<>'object' then raise exception 'Formato de backup inválido';end if;
 foreach t in array array['cineo_shows','cineo_episodes','cineo_profiles','cineo_categories','cineo_collections','cineo_editorial','cineo_preferences','cineo_ratings','cineo_lists','cineo_list_items','cineo_viewers','cineo_viewer_progress','cineo_viewer_saved','cineo_follows','cineo_progress','cineo_saved','cineo_likes','cineo_comments','cineo_comment_likes','cineo_show_info','cineo_episode_notes','cineo_polls','cineo_poll_votes','cineo_library_choices','cineo_bookmarks','cineo_experience','cineo_surveys','cineo_survey_votes','cineo_notices','cineo_feature_flags','cineo_release_news','cineo_tickets','cineo_appeals','cineo_cases','cineo_case_notes','cineo_case_actions','cineo_revisions','cineo_proposals']loop
 rows=coalesce(payload->'tables'->t,'[]');if jsonb_typeof(rows)<>'array' or jsonb_array_length(rows)>5000 then raise exception 'Tabela inválida no backup';end if;
 for uid_text in select distinct v.value#>>'{}' from jsonb_array_elements(rows) as r(rowdata) cross join lateral jsonb_each(r.rowdata) as v(key,value) where v.key in ('user_id','owner_id','author_id','assignee') and v.value<>'null'::jsonb loop if not exists(select 1 from auth.users where id=uid_text::uuid) or exists(select 1 from public.cineo_erasure where user_id=uid_text::uuid) then raise exception 'Uma conta referenciada não existe ou está em exclusão. O backup não restaura contas de autenticação.';end if;end loop;
 execute format('create temporary table %I (like public.%I including constraints) on commit drop','probe_'||t,t);
 execute format('insert into %I select * from jsonb_populate_recordset(null::public.%I,$1)','probe_'||t,t) using rows;get diagnostics n=row_count;added=0;
 if apply_missing and n>0 then execute format('insert into public.%I overriding system value select * from %I on conflict do nothing',t,'probe_'||t);get diagnostics added=row_count;end if;
 report=report||jsonb_build_array(jsonb_build_object('table',t,'checked',n,'inserted',added));end loop;
 return jsonb_build_object('ok',true,'applied',apply_missing,'tables',report,'mode','Somente registros ausentes. Dados existentes não são substituídos.','media_included',false,'auth_included',false);end$$;
revoke all on function public.cineo_backup_snapshot(),public.cineo_restore_metadata(jsonb,boolean) from public,anon,authenticated;
grant execute on function public.cineo_backup_snapshot(),public.cineo_restore_metadata(jsonb,boolean) to service_role;
